package com.example.courslens.service; import org.springframework.stereotype.Component; import java.nio.file.*; import java.util.*;
@Component class ImageDocumentExtractor implements DocumentExtractor {private final GeminiService gemini;ImageDocumentExtractor(GeminiService g){gemini=g;}public boolean supports(String t){return t.equals("IMAGE");}public List<ExtractedPage> extract(Path f,String mime)throws Exception{String text=gemini.readImage(Files.readAllBytes(f),mime);if(text.isBlank())throw new IllegalStateException("Gemini could not extract educational content from the image");return List.of(new ExtractedPage(1,text,true,"IMAGE"));}}
